export type ClinicalCase = { id:number; department:string; title:string; difficulty:'Basic'|'Intermediate'|'Advanced'; vignette:string; vitals:string; findings:string[]; diagnosis:string; differentials:string[]; investigations:string[]; reasoning:string[]; management:string[]; redFlags:string[]; takeaway:string; guideline:string };

const cases:ClinicalCase[] = [
{id:1,department:'Cardiology',title:'STEMI anterior',difficulty:'Advanced',vignette:'Pria 58 tahun dengan nyeri dada substernal menekan sejak 90 menit, menjalar ke lengan kiri, disertai diaforesis dan mual. Riwayat diabetes dan merokok.',vitals:'BP 92/60 · HR 104 · RR 22 · SpO₂ 95%',findings:['Nyeri dada tipikal','ST elevation V1–V4','Hipotensi','Onset <2 jam'],diagnosis:'ST-elevation myocardial infarction anterior.',differentials:['Aortic dissection','Pulmonary embolism','Pericarditis','Pneumothorax'],investigations:['ECG 12-lead segera dan serial bila perlu','Troponin dan pemeriksaan darah dasar tanpa menunda reperfusi','Monitor ritme kontinu','Evaluasi komplikasi mekanik/hemodinamik'],reasoning:['Diagnosis STEMI dapat ditegakkan dari gejala dan ECG yang konsisten.','Troponin membantu konfirmasi/stratifikasi tetapi bukan alasan menunda reperfusi.','Hipotensi harus memicu pencarian RV involvement, mechanical complication, arrhythmia, atau shock.'],management:['Aktifkan pathway reperfusi; primary PCI bila dapat dilakukan tepat waktu.','Aspirin loading dan terapi antitrombotik sesuai strategi reperfusi/protokol.','Oksigen bila hipoksemia; hindari nitrat pada hipotensi.','Statin intensitas tinggi dan terapi sekunder setelah stabil.'],redFlags:['Syok kardiogenik','VT/VF','Acute pulmonary edema','Acute MR/VSD/free-wall rupture'],takeaway:'Pada STEMI, waktu menuju reperfusi adalah target utama.',guideline:'2025 ACC/AHA/ACEP/NAEMSP/SCAI ACS Guideline; 2023 ESC ACS Guideline.'},
{id:2,department:'Cardiology',title:'Acute pulmonary edema hipertensif',difficulty:'Advanced',vignette:'Wanita 72 tahun dengan hipertensi lama mengalami sesak mendadak, orthopnea dan batuk berbusa. Crackles bilateral.',vitals:'BP 198/112 · HR 126 · RR 34 · SpO₂ 82%',findings:['Distress napas berat','Hipoksemia','Crackles difus','Severe hypertension'],diagnosis:'Acute cardiogenic pulmonary edema.',differentials:['Asthma/COPD','Pneumonia','PE','ACS'],investigations:['ECG','CXR/POCUS','Troponin','Renal function dan elektrolit'],reasoning:['Gambaran dominan adalah pulmonary congestion dengan tekanan darah sangat tinggi.','Kondisi ini membutuhkan kontrol preload/afterload dan dukungan ventilasi, bukan bolus cairan rutin.'],management:['Posisikan duduk dan monitor.','NIV/CPAP bila sesuai.','IV loop diuretic bila congestion jelas.','Vasodilator IV dapat dipertimbangkan pada hipertensi dengan monitoring ketat.','Cari dan terapi pencetus seperti ACS atau aritmia.'],redFlags:['Fatigue','Penurunan kesadaran','Shock','Refractory hypoxemia'],takeaway:'Pada edema paru hipertensif, ventilasi noninvasif dan kontrol hemodinamik sering lebih penting daripada cairan.',guideline:'ESC Heart Failure Guideline 2021 dan pembaruan terkait acute heart failure.'},
{id:3,department:'Respiratory',title:'Eksaserbasi asma berat',difficulty:'Advanced',vignette:'Perempuan 24 tahun setelah paparan debu sulit berbicara dalam kalimat penuh, menggunakan otot bantu napas dan wheezing difus.',vitals:'BP 138/82 · HR 132 · RR 32 · SpO₂ 89%',findings:['Unable to speak full sentences','Accessory muscle use','Tachypnea','Hypoxemia'],diagnosis:'Severe/life-threatening asthma exacerbation.',differentials:['Anaphylaxis','Pneumothorax','PE','Foreign body'],investigations:['Pulse oximetry serial','PEF bila mampu','Blood gas bila severe/deteriorating','ECG dan pemeriksaan penyebab bila diperlukan'],reasoning:['Severity ditentukan oleh kemampuan bicara, respiratory effort, oxygenation dan respons terhadap terapi.','Silent chest pada pasien yang memburuk adalah tanda sangat berat, bukan perbaikan.'],management:['Repeated inhaled SABA plus ipratropium pada serangan berat.','Systemic corticosteroid dini.','Oksigen titrasi sesuai target.','IV magnesium sulfate dapat dipertimbangkan bila respons buruk.','Eskalasi airway bila exhaustion, altered consciousness atau gagal terapi.'],redFlags:['Silent chest','Exhaustion','Confusion','Rising CO₂'],takeaway:'Berikan bronkodilator dan steroid dini, lalu reassess respons secara serial.',guideline:'GINA 2026 Strategy Report.'},
{id:4,department:'Respiratory',title:'COPD exacerbation dengan hypercapnia',difficulty:'Advanced',vignette:'Pria 68 tahun perokok dengan COPD mengalami peningkatan sesak dan sputum purulen. Mengantuk tetapi dapat dibangunkan.',vitals:'BP 146/84 · HR 112 · RR 30 · SpO₂ 84% room air',findings:['Known COPD','Increased dyspnea/sputum','Reduced consciousness','High risk hypercapnia'],diagnosis:'Acute COPD exacerbation with suspected acute hypercapnic respiratory failure.',differentials:['Pneumonia','ACS','PE','Heart failure','Pneumothorax'],investigations:['ABG/VBG sesuai kondisi','CXR','ECG','CBC/electrolytes','Evaluate infection and cardiac trigger'],reasoning:['Oksigen harus dikontrol karena pasien berisiko retensi CO₂.','Acidosis pada hypercapnic respiratory failure merupakan alasan penting untuk NIV bila tidak kontraindikasi.'],management:['Controlled oxygen, commonly target SpO₂ 88–92%.','SABA ± SAMA.','Systemic corticosteroid.','Antibiotic bila indikasi.','NIV bila acute hypercapnic respiratory failure dengan acidosis dan tidak kontraindikasi.','Intubasi bila NIV gagal atau kontraindikasi.'],redFlags:['Worsening acidosis','Reduced consciousness','Shock','NIV failure'],takeaway:'Pada COPD akut, target oksigen dan blood gas penting untuk mencegah overtreatment.',guideline:'GOLD 2026 Report.'},
{id:5,department:'Allergy',title:'Anafilaksis setelah antibiotik',difficulty:'Advanced',vignette:'Pria 34 tahun 10 menit setelah injeksi antibiotik mengalami urtikaria generalisata, suara serak, wheezing dan pusing.',vitals:'BP 78/46 · HR 132 · RR 28 · SpO₂ 88%',findings:['Rapid onset after trigger','Skin involvement','Airway/breathing compromise','Hypotension'],diagnosis:'Anaphylaxis with shock and airway involvement.',differentials:['Vasovagal reaction','Septic shock','Asthma','Isolated angioedema'],investigations:['Diagnosis klinis','Continuous monitoring','Tryptase hanya sebagai adjunct; jangan menunda terapi'],reasoning:['Anafilaksis adalah diagnosis klinis dan dapat terjadi tanpa manifestasi kulit.','Epinephrine IM adalah terapi pertama dan tidak boleh ditunda.'],management:['IM epinephrine segera di paha lateral.','Supine bila toleran dan oksigen sesuai kebutuhan.','IV crystalloid bila hipotensi.','Repeat epinephrine bila respons tidak adekuat.','Adjunct bronchodilator/airway management sesuai kondisi.'],redFlags:['Stridor','Progressive laryngeal edema','Persistent hypotension','Recurrent/biphasic reaction'],takeaway:'Jangan mengganti epinephrine dengan antihistamin atau steroid.',guideline:'WAO Anaphylaxis Guidance 2020; AAAAI/ACAAI practice parameter.'},
{id:6,department:'Infectious Disease',title:'Septic shock',difficulty:'Advanced',vignette:'Wanita 61 tahun dengan pneumonia, hipotensi, dingin dan oliguria. Lactate meningkat.',vitals:'BP 82/48 · HR 124 · RR 28 · SpO₂ 91% · T 39.1°C',findings:['Suspected infection','Hypotension','Hypoperfusion','Elevated lactate'],diagnosis:'Sepsis with septic shock physiology.',differentials:['Cardiogenic shock','Hypovolemia','Obstructive shock','Adrenal crisis'],investigations:['Blood cultures','Lactate serial','CBC/CMP','Source imaging as indicated','Urine and respiratory sampling when relevant'],reasoning:['Sepsis resuscitation harus berupa siklus intervention–reassessment.','Antibiotik dan source control sama pentingnya dengan resusitasi hemodinamik.'],management:['Ambil kultur tanpa menunda antibiotik.','Balanced crystalloid sering menjadi pilihan awal.','Norepinephrine sebagai vasopressor first-line bila hipotensi persisten.','Target awal MAP sekitar 65 mmHg pada dewasa.','Source control sedini mungkin.'],redFlags:['Persistent hypotension','Rising lactate','Oliguria','Altered mental status','Respiratory failure'],takeaway:'Hindari cairan tanpa batas; reassess perfusion setelah setiap intervensi.',guideline:'Surviving Sepsis Campaign 2021.'},
{id:7,department:'Neurology',title:'Convulsive status epilepticus',difficulty:'Advanced',vignette:'Pria 40 tahun mengalami kejang tonik-klonik terus-menerus >5 menit tanpa kembali ke baseline.',vitals:'BP 154/92 · HR 138 · RR 30 · SpO₂ 86%',findings:['Seizure >5 minutes','Hypoxemia','No return to baseline','Need time-based escalation'],diagnosis:'Convulsive status epilepticus.',differentials:['Hypoglycemia','Toxicologic seizure','PNES','Intracranial pathology'],investigations:['Point-of-care glucose','Electrolytes','Drug/toxin review','Neuroimaging after stabilization when indicated'],reasoning:['Kejang ≥5 menit diperlakukan sebagai status epileptikus emergensi.','Terapi harus berbasis waktu: benzodiazepine lalu second-line antiseizure therapy bila berlanjut.'],management:['ABC, oxygen, monitor dan IV/IO access.','Check glucose segera.','Benzodiazepine first-line.','Second-line levetiracetam/valproate/fosphenytoin sesuai konteks.','Refractory status memerlukan ICU dan anesthetic therapy.'],redFlags:['Persistent seizures','Hypoxia','Hyperthermia','Acidosis','Refractory status'],takeaway:'Jangan menunggu imaging untuk menghentikan status yang sedang berlangsung.',guideline:'Neurocritical Care Society guideline; American Epilepsy Society evidence-based treatment.'},
{id:8,department:'Neurology',title:'Acute ischemic stroke',difficulty:'Advanced',vignette:'Pria 67 tahun tiba 70 menit setelah onset afasia dan hemiparesis kanan. Last-known-well jelas.',vitals:'BP 184/102 · HR 88 · SpO₂ 96% · Glucose 128 mg/dL',findings:['Focal neurologic deficit','Known onset','Possible LVO','BP relevant to reperfusion eligibility'],diagnosis:'Acute ischemic stroke, likely left hemispheric syndrome.',differentials:['ICH','Hypoglycemia','Postictal deficit','Migraine aura'],investigations:['Stroke code/NIHSS','Noncontrast CT','CTA head/neck when LVO suspected','Glucose','Determine thrombolysis/thrombectomy eligibility'],reasoning:['Time, imaging, deficit severity dan vessel status menentukan reperfusion pathway.','Jangan menunda evaluasi reperfusi karena pemeriksaan yang tidak esensial.'],management:['IV thrombolysis bila eligible dalam window yang sesuai.','Mechanical thrombectomy untuk eligible LVO termasuk selected extended-window patients.','Kontrol suhu, glucose dan oxygenation.','Stroke-unit care.'],redFlags:['Reduced consciousness','Large infarct','Airway compromise','Neurologic deterioration'],takeaway:'Catat last-known-well dan aktifkan stroke pathway segera.',guideline:'2026 AHA/ASA Guideline for Early Management of Acute Ischemic Stroke.'},
{id:9,department:'Neurology',title:'Spontaneous intracerebral hemorrhage',difficulty:'Advanced',vignette:'Pria 59 tahun hipertensi mendadak sakit kepala, muntah dan hemiparesis. CT menunjukkan perdarahan ganglia basalis.',vitals:'BP 218/118 · HR 74 · GCS 12',findings:['ICH on CT','Severe hypertension','Focal deficit','Risk of expansion/ICP'],diagnosis:'Spontaneous intracerebral hemorrhage.',differentials:['Hemorrhagic transformation','SAH','Tumor bleed','Coagulopathy'],investigations:['Urgent CT ± CTA','CBC/coagulation','Medication review','Serial neurological assessment'],reasoning:['Prioritas adalah mencegah secondary brain injury.','Anticoagulant reversal bila relevan harus dilakukan cepat.'],management:['Airway dan neurocritical monitoring.','Controlled BP lowering sesuai ICH pathway.','Reverse anticoagulation promptly when indicated.','Manage hydrocephalus/raised ICP.','Neurosurgical consultation for selected cases.'],redFlags:['GCS decline','Pupillary asymmetry','Hydrocephalus','Posterior fossa bleed'],takeaway:'BP, anticoagulant reversal, ICP dan neurosurgical assessment merupakan pilar awal.',guideline:'2022 AHA/ASA Guideline for Spontaneous ICH.'},
{id:10,department:'Emergency',title:'Tension pneumothorax',difficulty:'Advanced',vignette:'Pria 29 tahun pascatrauma dada mengalami sesak progresif, hipotensi, distensi vena leher dan suara napas unilateral menurun.',vitals:'BP 78/50 · HR 136 · RR 34 · SpO₂ 82%',findings:['Trauma','Shock','Unilateral absent breath sounds','Respiratory failure'],diagnosis:'Tension pneumothorax.',differentials:['Massive hemothorax','Tamponade','Massive PE'],investigations:['Clinical diagnosis in unstable classic presentation','POCUS/CXR only if it will not delay decompression'],reasoning:['Tension pneumothorax adalah diagnosis klinis pada pasien tidak stabil.','Imaging tidak boleh menunda decompression.'],management:['Immediate decompression menggunakan teknik sesuai kompetensi dan trauma protocol.','Definitive tube thoracostomy.','Oxygen dan trauma resuscitation.','Reassess immediately after decompression.'],redFlags:['Persistent shock','Persistent hypoxia','Bilateral trauma','Need for PPV'],takeaway:'Treat first when the clinical picture is classic and unstable.',guideline:'ATLS principles and local trauma protocol.'},
{id:11,department:'Emergency',title:'High-risk pulmonary embolism',difficulty:'Advanced',vignette:'Wanita 46 tahun 8 hari pascaoperasi mengalami sinkop dan sesak mendadak. BP 82/54 dengan tanda RV strain.',vitals:'BP 82/54 · HR 128 · RR 30 · SpO₂ 89%',findings:['Recent surgery','Syncope','Shock','RV strain'],diagnosis:'High-risk pulmonary embolism with obstructive shock.',differentials:['ACS','Aortic dissection','Tension pneumothorax','Cardiogenic shock'],investigations:['Bedside echocardiography','CTPA if stable enough','ECG/troponin/BNP as supportive','Bleeding-risk assessment'],reasoning:['Hemodynamic instability defines a high-risk pathway.','Large fluid boluses may worsen RV failure.'],management:['Oxygen/ventilatory support.','Norepinephrine or appropriate vasopressor for shock.','Anticoagulation when appropriate.','Systemic thrombolysis or catheter/surgical reperfusion in selected high-risk patients.'],redFlags:['Cardiac arrest','Persistent hypotension','Severe RV dysfunction','High bleeding risk'],takeaway:'In unstable PE, diagnostic and reperfusion decisions must occur in parallel.',guideline:'2019 ESC/ERS Acute Pulmonary Embolism Guideline and updates.'},
{id:12,department:'Gastroenterology',title:'Upper GI bleeding',difficulty:'Advanced',vignette:'Pria 55 tahun hematemesis dan melena, riwayat NSAID, pusing saat berdiri.',vitals:'BP 88/56 · HR 118 · RR 22 · SpO₂ 96%',findings:['Overt GI bleeding','Hemodynamic instability','NSAID exposure','Likely nonvariceal source'],diagnosis:'Acute upper GI bleeding, likely peptic ulcer bleeding.',differentials:['Variceal bleed','Mallory-Weiss','Malignancy','Dieulafoy lesion'],investigations:['CBC','Urea/creatinine','Coagulation','Type and crossmatch','Risk score and endoscopy pathway'],reasoning:['Stabilization dilakukan bersamaan dengan persiapan definitive source control.','Variceal bleeding membutuhkan pathway berbeda.'],management:['Large-bore IV access and resuscitation.','Blood products based on clinical status and threshold.','IV PPI in suspected nonvariceal bleeding pathway.','Urgent endoscopy after stabilization.','If variceal suspected: vasoactive therapy + antibiotics + urgent endoscopy.'],redFlags:['Shock','Massive hematemesis','Altered consciousness','Cirrhosis','Rebleeding'],takeaway:'Resuscitate, stratify, then achieve timely endoscopic hemostasis.',guideline:'ACG Upper Gastrointestinal and Ulcer Bleeding Guideline; ESGE guideline.'},
{id:13,department:'Surgery',title:'Perforated viscus',difficulty:'Advanced',vignette:'Pria 63 tahun nyeri epigastrium mendadak menjadi generalisata, abdomen board-like dan demam.',vitals:'BP 94/58 · HR 124 · RR 28 · T 38.7°C',findings:['Sudden severe pain','Generalized peritonitis','Sepsis physiology','Possible free air'],diagnosis:'Perforated viscus with secondary peritonitis.',differentials:['Pancreatitis','Mesenteric ischemia','Ruptured AAA','Bowel obstruction'],investigations:['CBC/CMP/lactate','CT abdomen if stable','Imaging for free air when appropriate','Blood cultures if septic'],reasoning:['Peritonitis dari perforasi adalah source-control emergency.','Antibiotik saja biasanya tidak cukup pada perforasi yang membutuhkan operasi.'],management:['Resuscitation with reassessment.','Broad-spectrum antibiotics covering GI flora.','NPO ± NG decompression.','Urgent surgical evaluation and source control.'],redFlags:['Shock','Diffuse peritonitis','Rising lactate','Delayed source control'],takeaway:'Jangan membiarkan imaging menunda konsultasi bedah pada peritonitis yang jelas.',guideline:'WSES guidance for perforated peptic ulcer and intra-abdominal infection.'},
{id:14,department:'Vascular',title:'Acute aortic dissection',difficulty:'Advanced',vignette:'Pria 64 tahun hipertensi dengan nyeri dada-punggung mendadak maksimal sejak awal dan perbedaan nadi antar lengan.',vitals:'BP 196/104 right arm · HR 118',findings:['Abrupt maximal-onset pain','Pulse/BP differential','Hypertension','Possible malperfusion'],diagnosis:'Acute aortic syndrome, likely Stanford type A until proven otherwise.',differentials:['ACS','PE','Pneumothorax','Esophageal rupture'],investigations:['Urgent CTA when stable','Bedside echo as adjunct','ECG/troponin but interpret in context','Assess branch-vessel malperfusion'],reasoning:['Clinical suspicion harus tinggi karena antithrombotic therapy untuk ACS dapat berbahaya bila dissection belum dieksklusi.','Anti-impulse therapy menurunkan shear stress sambil menyiapkan definitive repair.'],management:['IV beta-blockade when appropriate.','Add vasodilator only after adequate beta blockade if BP remains high.','Analgesia.','Emergent surgery for type A.','Complicated type B requires specialist aortic pathway.'],redFlags:['Tamponade','Coronary ischemia','Acute AR','Stroke','Malperfusion'],takeaway:'Acute chest pain with pulse deficit is a dissection-until-excluded scenario.',guideline:'2024 ESC Guidelines for peripheral arterial and aortic diseases; ACC/AHA aortic disease guidance.'},
{id:15,department:'Electrolytes',title:'Hyperkalemia dengan ECG toxicity',difficulty:'Advanced',vignette:'Pasien CKD dengan weakness dan palpitasi. ECG menunjukkan peaked T waves dan QRS melebar.',vitals:'BP 108/68 · HR 96 · SpO₂ 98%',findings:['CKD','ECG toxicity','Likely severe hyperkalemia','Arrhythmia risk'],diagnosis:'Severe hyperkalemia with cardiac membrane toxicity.',differentials:['Sodium-channel blocker toxicity','MI with conduction disease','Hypocalcemia'],investigations:['Urgent potassium','Repeat ECG','Renal function','Blood gas when relevant','Medication review'],reasoning:['ECG toxicity adalah alasan untuk segera menstabilkan membran.','Calcium tidak mengeluarkan potassium; diperlukan redistribution dan elimination.'],management:['IV calcium according to protocol.','Insulin + glucose.','Nebulized beta-2 agonist as adjunct.','Potassium removal with diuresis/binder/dialysis according to context.','Repeat ECG and potassium.'],redFlags:['QRS widening','Bradyarrhythmia','Ventricular arrhythmia','Anuria'],takeaway:'Treat ECG toxicity immediately while simultaneously lowering total body potassium.',guideline:'AHA resuscitation/electrolyte guidance and contemporary hyperkalemia recommendations.'},
{id:16,department:'Endocrinology',title:'Diabetic ketoacidosis',difficulty:'Advanced',vignette:'Wanita 23 tahun DM tipe 1 berhenti insulin karena muntah. Nyeri perut, Kussmaul dan dehidrasi.',vitals:'BP 96/62 · HR 126 · RR 32 · SpO₂ 98%',findings:['Insulin omission','Ketosis/acidosis','Volume depletion','Potassium total-body deficit'],diagnosis:'Diabetic ketoacidosis.',differentials:['HHS','Lactic acidosis','Starvation ketosis','Toxic alcohol'],investigations:['Glucose','Beta-hydroxybutyrate','Venous pH','Electrolytes','Renal function','Identify trigger'],reasoning:['Tujuan terapi adalah menghentikan ketogenesis, memperbaiki volume dan elektrolit.','Serum K dapat normal/tinggi meskipun total-body K rendah.'],management:['Isotonic/balanced crystalloid with reassessment.','IV insulin when potassium permits.','Potassium replacement based on serial K.','Add dextrose when glucose falls while ketosis persists.','Treat precipitant.'],redFlags:['Shock','Altered consciousness','Severe hypokalemia','Cerebral injury risk'],takeaway:'Jangan hanya mengejar normalisasi glucose; insulin dilanjutkan sampai ketoacidosis teratasi.',guideline:'2024 International Consensus Report on Hyperglycemic Crises in Adults With Diabetes.'},
{id:17,department:'Endocrinology',title:'Severe hypoglycemia',difficulty:'Intermediate',vignette:'Pria 70 tahun menggunakan insulin ditemukan berkeringat, bingung dan tidak mampu menelan. Glucose 38 mg/dL.',vitals:'BP 136/78 · HR 102 · RR 20 · glucose 38 mg/dL',findings:['Neuroglycopenia','Unable to swallow','Insulin exposure','Risk recurrence'],diagnosis:'Severe hypoglycemia.',differentials:['Stroke','Seizure','Sepsis','Drug intoxication'],investigations:['Point-of-care glucose serial','Medication review','Renal function','Evaluate recurrence'],reasoning:['Airway dan koreksi glucose adalah prioritas.','Sulfonylurea dan renal failure meningkatkan risiko recurrent hypoglycemia.'],management:['IV dextrose according to local protocol if IV access.','Glucagon if IV unavailable and appropriate.','Recheck glucose after treatment.','Once awake, provide sustained carbohydrate/meal when safe.','Observe longer for long-acting insulin/sulfonylurea.'],redFlags:['Persistent altered mental status','Recurrent hypoglycemia','Sulfonylurea exposure','Renal failure'],takeaway:'Recheck glucose and investigate the cause after initial reversal.',guideline:'ADA Standards of Care 2026.'},
{id:18,department:'Toxicology',title:'Opioid toxicity',difficulty:'Advanced',vignette:'Pria 32 tahun tidak responsif, pupil pinpoint dan RR 6/min. Diduga opioid.',vitals:'BP 104/68 · HR 58 · RR 6 · SpO₂ 74%',findings:['Respiratory depression','Miosis','Hypoxemia','Possible long-acting opioid'],diagnosis:'Opioid-induced respiratory depression.',differentials:['Benzodiazepine toxicity','ICH','Hypoglycemia','Mixed overdose'],investigations:['Clinical toxidrome','Glucose','ECG','Assess trauma/co-ingestants','Observe for recurrence'],reasoning:['Ventilation adalah prioritas; naloxone adalah adjunct.','Target reversal adalah adequate breathing, bukan harus sadar penuh.'],management:['Airway positioning and bag-mask ventilation when needed.','Naloxone titrated to restore adequate ventilation.','Repeat doses or infusion for long-acting opioids.','Monitor for recurrent toxicity and pulmonary complications.'],redFlags:['Recurrent apnea','Long-acting opioid','Pulmonary edema','Mixed ingestion'],takeaway:'Ventilate first and titrate naloxone to respiratory recovery.',guideline:'AHA CPR/ECC toxicology guidance and contemporary opioid overdose recommendations.'},
{id:19,department:'Toxicology',title:'Organophosphate poisoning',difficulty:'Advanced',vignette:'Petani 45 tahun setelah menyemprot pestisida mengalami miosis, salivasi, wheezing, muntah dan fasciculations.',vitals:'BP 96/58 · HR 54 · RR 30 · SpO₂ 82%',findings:['Cholinergic toxidrome','Bronchorrhea','Bronchospasm','Bradycardia'],diagnosis:'Organophosphate poisoning with cholinergic crisis.',differentials:['Carbamate poisoning','Opioid toxicity','Asthma','Nicotine toxicity'],investigations:['Clinical diagnosis','Cholinesterase may support but should not delay treatment','Electrolytes/ECG','Assess co-exposure'],reasoning:['Airway contamination from secretions is a major cause of death.','Atropine endpoint adalah kontrol bronchorrhea/bronchospasm, bukan normalisasi pupil.'],management:['Responder safety and decontamination.','Airway suction/oxygen/ventilation.','Atropine repeated/escalated to clinical endpoint.','Pralidoxime early when indicated by protocol.','Benzodiazepine for seizures.'],redFlags:['Respiratory failure','Massive secretions','Fasciculations/weakness','Intermediate syndrome'],takeaway:'Atropinize to dry dangerous respiratory secretions and improve ventilation.',guideline:'WHO/clinical toxicology guidance and local poison-center protocol.'},
{id:20,department:'Emergency',title:'Exertional heat stroke',difficulty:'Advanced',vignette:'Pelari 27 tahun kolaps setelah latihan di cuaca panas. Suhu inti 41.2°C dan bingung.',vitals:'BP 92/54 · HR 148 · RR 34 · T 41.2°C',findings:['Core temperature >40°C','CNS dysfunction','Heat exposure','Shock risk'],diagnosis:'Exertional heat stroke.',differentials:['Sepsis','NMS','Serotonin syndrome','Malignant hyperthermia'],investigations:['Core temperature','Glucose','Electrolytes','CK/renal function','Coagulation/liver function'],reasoning:['Heat stroke adalah diagnosis klinis emergensi.','Cooling adalah definitive emergency treatment dan tidak boleh menunggu hasil lab.'],management:['Immediate active cooling.','Cold-water immersion when feasible for exertional heat stroke.','IV access and cautious fluid support.','Treat seizures with benzodiazepines.','Monitor rhabdomyolysis, AKI, DIC and hepatic injury.'],redFlags:['Persistent hyperthermia','Altered consciousness','Hypotension','Rhabdomyolysis','Coagulopathy'],takeaway:'Cool first while resuscitating and monitoring for multiorgan failure.',guideline:'Wilderness Medical Society heat illness guideline.'},
{id:21,department:'Cardiology',title:'Atrial fibrillation with RVR',difficulty:'Intermediate',vignette:'Pria 70 tahun berdebar dan sesak. ECG menunjukkan AF dengan ventricular rate 150/min. Hemodinamik stabil.',vitals:'BP 128/76 · HR 150 irregular · RR 22 · SpO₂ 96%',findings:['Irregularly irregular rhythm','Stable BP','Assess onset/duration','Stroke risk'],diagnosis:'Atrial fibrillation with rapid ventricular response.',differentials:['Atrial flutter','SVT','MAT'],investigations:['12-lead ECG','Electrolytes','Thyroid testing when appropriate','Assess HF/ischemia','Stroke and bleeding risk'],reasoning:['Stability menentukan urgensi cardioversion.','Trigger dan duration mempengaruhi rhythm strategy dan anticoagulation.'],management:['Rate control with beta-blocker or non-DHP CCB when appropriate.','Avoid AV-nodal blockers in selected pre-excited AF/decompensated HFrEF.','Anticoagulation according to validated pathway.','Urgent synchronized cardioversion if unstable.'],redFlags:['Shock','Ischemia','Pulmonary edema','Pre-excited AF'],takeaway:'Start with stability, then rate/rhythm and thromboembolism strategy.',guideline:'2024 ESC Atrial Fibrillation Guideline.'},
{id:22,department:'Cardiology',title:'Symptomatic bradycardia',difficulty:'Intermediate',vignette:'Wanita 76 tahun pusing dan hampir sinkop. ECG sinus bradycardia 38/min.',vitals:'BP 84/52 · HR 38 · RR 18 · SpO₂ 98%',findings:['Symptomatic bradycardia','Hypotension','Possible conduction disease','Need pacing readiness'],diagnosis:'Hemodynamically significant symptomatic bradycardia.',differentials:['High-grade AV block','Inferior MI','Drug toxicity','Hyperkalemia'],investigations:['ECG','Electrolytes','Medication review','Troponin when ischemia suspected'],reasoning:['Cari reversible causes tetapi jangan menunda treatment pada instability.','Prepare pacing early when atropine is unlikely to work.'],management:['Atropine according to ACLS protocol when appropriate.','If ineffective, transcutaneous pacing and/or vasoactive infusion per protocol.','Treat cause.','Cardiology review for definitive pacing when indicated.'],redFlags:['High-grade AV block','Syncope','Shock','Wide QRS escape'],takeaway:'Instability plus bradycardia requires immediate treatment and pacing readiness.',guideline:'AHA Adult Advanced Life Support guidance.'},
{id:23,department:'Cardiology',title:'Acute pericarditis',difficulty:'Intermediate',vignette:'Pria 31 tahun nyeri dada tajam memburuk saat inspirasi dan membaik saat duduk membungkuk. ECG diffuse ST elevation dan PR depression.',vitals:'BP 122/76 · HR 94 · RR 18 · SpO₂ 98%',findings:['Pleuritic positional pain','Diffuse ST elevation','PR depression','Assess effusion'],diagnosis:'Acute pericarditis.',differentials:['STEMI','PE','Myocarditis','Dissection'],investigations:['ECG','Troponin','Inflammatory markers','Echocardiography','Etiologic testing when indicated'],reasoning:['Diffuse ECG changes dan positional pain mendukung pericarditis.','Troponin elevation suggests myocardial involvement and changes risk assessment.'],management:['NSAID/aspirin plus colchicine when appropriate.','Gastroprotection when indicated.','Exercise restriction during active inflammation.','Treat underlying cause.'],redFlags:['Tamponade','Large effusion','Fever','Myocardial involvement'],takeaway:'Differentiate territorial ischemia from diffuse inflammatory ECG changes while excluding dangerous mimics.',guideline:'2015 ESC Pericardial Disease Guideline and updates.'},
{id:24,department:'Cardiology',title:'Acute decompensated heart failure',difficulty:'Intermediate',vignette:'Pria 65 tahun HFrEF mengalami edema tungkai, orthopnea dan kenaikan berat 4 kg dalam seminggu.',vitals:'BP 142/86 · HR 106 · RR 24 · SpO₂ 92%',findings:['Congestion','Recent weight gain','Known HFrEF','Need trigger search'],diagnosis:'Acute decompensated heart failure with congestion.',differentials:['Renal failure','Nephrotic syndrome','Liver disease','Pulmonary disease'],investigations:['ECG','CXR/POCUS','Renal/electrolytes','Troponin when indicated','Assess infection/arrhythmia'],reasoning:['Klasifikasikan congestion dan perfusion sebelum menentukan terapi.','Cari pencetus karena outcome bergantung pada koreksi precipitant.'],management:['IV loop diuretic.','Titrate to urine output and decongestion.','Vasodilator if hypertensive and appropriate.','Adjust chronic HF therapy according to hemodynamics/renal function.'],redFlags:['Cold/clammy shock','Severe hypoxemia','Cardiogenic shock','New ischemia'],takeaway:'Bedside phenotype congestion-versus-perfusion guides acute therapy.',guideline:'2021 ESC Heart Failure Guideline.'},
{id:25,department:'Pediatrics',title:'Dehidrasi akibat gastroenteritis',difficulty:'Intermediate',vignette:'Anak 3 tahun diare 2 hari, intake turun, mata cekung dan urin sedikit. Tidak ada shock.',vitals:'HR 126 · RR 28 · CRT 2–3 s · T 38.4°C',findings:['Reduced intake/output','Sunken eyes','No shock','Assess mental status'],diagnosis:'Acute gastroenteritis with moderate dehydration.',differentials:['Sepsis','DKA','Surgical abdomen','Meningitis'],investigations:['Clinical dehydration assessment','Electrolytes if severe','Glucose when altered or severe','Weight if available'],reasoning:['Sebagian besar dehidrasi anak dapat ditangani dengan ORS.','IV fluid dipilih bila severe dehydration, shock, atau oral route gagal.'],management:['ORS frequent small amounts when able.','IV isotonic crystalloid if severe/failed oral therapy.','Continue feeding/breastfeeding.','Zinc according to local guidance.','Monitor urine and electrolytes if severe.'],redFlags:['Lethargy','Unable to drink','Persistent vomiting','Shock','Bloody stool'],takeaway:'Pilih ORS untuk mayoritas kasus; hindari over-resuscitation.',guideline:'WHO diarrhoea/dehydration guidance and IMCI.'},
{id:26,department:'Pediatrics',title:'Bronchiolitis bayi',difficulty:'Intermediate',vignette:'Bayi 5 bulan pilek 3 hari, takipnea, wheezing/crackles dan feeding turun.',vitals:'HR 156 · RR 62 · SpO₂ 90%',findings:['Viral prodrome','Age <1 year','Increased work of breathing','Reduced feeding'],diagnosis:'Acute bronchiolitis.',differentials:['Pneumonia','Asthma','Foreign body','Heart failure'],investigations:['Clinical assessment','Oxygen saturation','No routine CXR/lab in typical disease'],reasoning:['Severity ditentukan respiratory effort, oxygenation dan hydration.','Routine bronchodilator, steroid dan antibiotic tidak bermanfaat pada typical bronchiolitis.'],management:['Supportive care.','Oxygen according to local threshold.','Nasal suction before feeds.','NG/IV hydration if oral intake inadequate.','Escalate respiratory support if worsening.'],redFlags:['Apnea','Cyanosis','Exhaustion','Severe retractions','Dehydration'],takeaway:'Supportive care is the treatment; assess feeding and work of breathing repeatedly.',guideline:'AAP Bronchiolitis Clinical Practice Guideline.'},
{id:27,department:'Pediatrics',title:'Croup dengan stridor',difficulty:'Intermediate',vignette:'Anak 2 tahun barking cough, suara serak dan stridor inspirasi saat gelisah.',vitals:'HR 128 · RR 30 · SpO₂ 95%',findings:['Barking cough','Hoarseness','Inspiratory stridor','Symptoms worse with agitation'],diagnosis:'Viral croup, moderate severity.',differentials:['Epiglottitis','Bacterial tracheitis','Foreign body','Anaphylaxis'],investigations:['Clinical assessment; imaging usually unnecessary in typical croup'],reasoning:['Stridor at rest menandakan penyakit lebih berat.','Anak harus tetap tenang untuk mencegah worsening airway obstruction.'],management:['Keep child calm.','Dexamethasone single dose per protocol.','Nebulized epinephrine for significant stridor at rest/moderate-severe disease.','Observe after epinephrine.'],redFlags:['Stridor at rest worsening','Drooling','Tripod','Cyanosis','Reduced consciousness'],takeaway:'Calm handling is part of airway management.',guideline:'Pediatric emergency croup guidance.'},
{id:28,department:'Pediatrics',title:'Complex febrile seizure',difficulty:'Intermediate',vignette:'Anak 18 bulan demam 39.5°C mengalami kejang 12 menit dan memiliki fitur fokal.',vitals:'HR 150 · RR 30 · SpO₂ 97%',findings:['Age 6 months–5 years','Fever-associated seizure','Prolonged','Focal feature'],diagnosis:'Complex febrile seizure; CNS infection must be considered.',differentials:['Meningitis/encephalitis','Epilepsy','Hypoglycemia','Intracranial lesion'],investigations:['Glucose','Focused neurologic/infection assessment','LP only when clinically indicated','Imaging/EEG based on atypical findings'],reasoning:['Complex features change the evaluation.','Fever alone should not end neurologic assessment.'],management:['Terminate ongoing prolonged seizure with benzodiazepine.','Treat suspected CNS infection promptly.','Antipyretics for comfort, not seizure prevention.','Specialist assessment for atypical/recurrent cases.'],redFlags:['Meningeal signs','Persistent altered consciousness','Focal deficit','Bulging fontanelle'],takeaway:'Complex features require assessment beyond “just febrile seizure”.',guideline:'AAP febrile seizure guidance and pediatric emergency protocols.'},
{id:29,department:'Pediatrics',title:'Pediatric DKA',difficulty:'Advanced',vignette:'Remaja 15 tahun DM tipe 1 muntah, poliuria dan napas dalam.',vitals:'BP 102/66 · HR 124 · RR 30 · SpO₂ 99%',findings:['Ketosis/acidosis','Dehydration','Vomiting','Cerebral injury risk'],diagnosis:'Pediatric diabetic ketoacidosis.',differentials:['Gastroenteritis','Sepsis','Toxic ingestion','Appendicitis'],investigations:['Glucose/ketones','VBG','Electrolytes','Neurologic monitoring','Identify trigger'],reasoning:['Koreksi harus terkontrol karena anak berisiko cerebral injury.','Insulin diberikan tanpa routine bolus dan potassium dipantau ketat.'],management:['Isotonic fluid per pediatric DKA protocol.','IV insulin after initial assessment.','Potassium replacement according to serial values.','Add dextrose as glucose falls while ketosis persists.','Treat cerebral injury immediately if suspected.'],redFlags:['Headache','Bradycardia','Altered consciousness','Neurologic deterioration'],takeaway:'Pediatric DKA membutuhkan monitoring neurologis dan elektrolit yang ketat.',guideline:'ISPAD pediatric DKA consensus guidance.'},
{id:30,department:'Obstetrics',title:'Preeclampsia dengan severe features',difficulty:'Advanced',vignette:'Ibu hamil 34 minggu sakit kepala hebat dan pandangan kabur. BP berulang 172/112 mmHg.',vitals:'BP 172/112 · HR 92 · RR 20 · SpO₂ 98%',findings:['Severe-range BP','Neurologic symptoms','Pregnancy >20 weeks','Eclampsia risk'],diagnosis:'Preeclampsia with severe features.',differentials:['Chronic hypertension','Migraine','ICH/CVT','HELLP'],investigations:['CBC/platelets','AST/ALT','Creatinine','Urine protein assessment','Fetal assessment'],reasoning:['Severe-range BP adalah obstetric emergency.','Magnesium sulfate mencegah kejang tetapi bukan pengganti BP control atau definitive obstetric management.'],management:['Urgent antihypertensive treatment for persistent severe BP.','Magnesium sulfate for seizure prophylaxis when indicated.','Corticosteroid if preterm delivery anticipated, without delaying necessary delivery.','Obstetric planning based on maternal-fetal status.'],redFlags:['Eclampsia','Pulmonary edema','HELLP','Abruption','Fetal compromise'],takeaway:'Stabilize mother urgently, then determine timing and mode of delivery.',guideline:'ACOG Practice Bulletin: Gestational Hypertension and Preeclampsia.'},
{id:31,department:'Obstetrics',title:'Eclampsia',difficulty:'Advanced',vignette:'Ibu hamil 36 minggu dengan preeclampsia mengalami generalized tonic-clonic seizure.',vitals:'BP 180/118 · HR 110 · SpO₂ 90%',findings:['Pregnancy + seizure','Severe hypertension','Aspiration risk','Maternal-fetal emergency'],diagnosis:'Eclampsia.',differentials:['Epilepsy','ICH','Cerebral venous thrombosis','Hypoglycemia'],investigations:['Glucose','CBC/platelets','Liver/renal function','Fetal assessment','Imaging only if atypical/persistent neurologic concern'],reasoning:['Magnesium sulfate adalah anticonvulsant first-line.','Delivery dilakukan setelah maternal stabilization, dengan mode sesuai obstetric factors.'],management:['Airway protection and left lateral positioning when feasible.','IV magnesium sulfate loading/maintenance per protocol.','Urgent BP control with labetalol/hydralazine/nifedipine protocol.','Delivery after stabilization.'],redFlags:['Persistent seizure','Pulmonary edema','Stroke','HELLP','Fetal distress'],takeaway:'Stabilize airway, seizure and BP first; delivery follows stabilization.',guideline:'ACOG and WHO preeclampsia/eclampsia recommendations.'},
{id:32,department:'Obstetrics',title:'Postpartum hemorrhage karena uterine atony',difficulty:'Advanced',vignette:'30 menit setelah persalinan vaginal, perdarahan banyak dan uterus lembek.',vitals:'BP 86/54 · HR 128 · RR 24 · SpO₂ 94%',findings:['Primary PPH','Boggy uterus','Shock','Need simultaneous resuscitation/source control'],diagnosis:'Postpartum hemorrhage due to uterine atony.',differentials:['Retained products','Genital tract trauma','Coagulopathy','Uterine rupture'],investigations:['Quantify blood loss','CBC/coagulation','Type/crossmatch','Assess 4 Ts'],reasoning:['Management berjalan paralel: resuscitation, uterine treatment, identification of 4 Ts dan escalation.'],management:['Uterine massage.','Oxytocin first-line uterotonic.','TXA early when PPH diagnosed within recommended window.','Additional uterotonics according to contraindications.','Balloon tamponade/surgery and massive transfusion pathway if refractory.'],redFlags:['Persistent bleeding','Shock','Coagulopathy','Accreta risk','Failure of uterotonics'],takeaway:'Do not wait for one intervention to fail before escalating the hemorrhage pathway.',guideline:'WHO PPH recommendations; FIGO/ACOG guidance.'},
{id:33,department:'Obstetrics',title:'Ruptured ectopic pregnancy',difficulty:'Advanced',vignette:'Wanita 29 tahun amenore 7 minggu, nyeri abdomen unilateral, pusing dan shoulder-tip pain. Pregnancy test positif.',vitals:'BP 82/50 · HR 126 · RR 24 · SpO₂ 98%',findings:['Positive pregnancy test','First trimester pain','Shock','Likely hemoperitoneum'],diagnosis:'Ruptured ectopic pregnancy with hemorrhagic shock.',differentials:['Miscarriage','Ovarian torsion','Ruptured corpus luteum','Appendicitis'],investigations:['POCUS for free fluid','CBC/type and crossmatch','No serial hCG delay in unstable patient'],reasoning:['Pregnancy plus shock and abdominal pain is ectopic until proven otherwise.','Definitive surgery should not be delayed for serial testing in unstable patients.'],management:['Hemorrhage resuscitation with blood products.','Urgent operative management.','Rh prophylaxis according to local policy.','Postoperative counseling/follow-up.'],redFlags:['Shock','Syncope','Hemoperitoneum','Peritonitis'],takeaway:'In an unstable pregnant patient, prioritize hemorrhage control over diagnostic perfection.',guideline:'ACOG Practice Bulletin: Tubal Ectopic Pregnancy.'},
{id:34,department:'Obstetrics',title:'Fetal compromise during labor',difficulty:'Advanced',vignette:'Ibu inpartu 39 minggu dengan CTG recurrent late decelerations dan baseline fetal HR 170/min.',vitals:'Maternal BP 132/80 · HR 96 · fetal baseline 170',findings:['Abnormal fetal heart tracing','Prolonged labor','Assess tachysystole','Need time-limited escalation'],diagnosis:'Suspected fetal compromise during labor.',differentials:['Maternal fever','Abruption','Tachysystole','Cord compression'],investigations:['Continuous CTG','Maternal vitals/temperature','Assess contractions','Fetal assessment per local protocol'],reasoning:['Koreksi reversible causes harus segera dilakukan.','Jika tracing tetap patologis, waktu menuju delivery menjadi critical.'],management:['Maternal repositioning and correct reversible causes.','Stop/reduce oxytocin if tachysystole.','Treat maternal hypotension/fever.','Urgent obstetric review for expedited birth.'],redFlags:['Persistent Category III pattern','Bradycardia','Abruption','Uterine rupture'],takeaway:'Every abnormal tracing needs a documented corrective action and escalation deadline.',guideline:'FIGO intrapartum fetal monitoring guidance and local CTG protocol.'},
{id:35,department:'Surgery',title:'Acute appendicitis',difficulty:'Intermediate',vignette:'Pria 22 tahun nyeri berpindah dari periumbilikal ke RLQ, anoreksia dan demam ringan.',vitals:'BP 122/76 · HR 104 · RR 18 · T 38.0°C',findings:['Migratory pain','RLQ tenderness','Anorexia','Assess peritonitis'],diagnosis:'Acute appendicitis.',differentials:['Mesenteric adenitis','Renal colic','Gastroenteritis','Ectopic pregnancy when relevant'],investigations:['CBC/CRP','Pregnancy test when relevant','US/CT according to pathway','Clinical risk score as adjunct'],reasoning:['Diagnosis is clinical plus selective imaging.','Analgesia should not be withheld while evaluating.'],management:['Analgesia and hydration.','Antibiotics when indicated.','Appendectomy for appropriate cases.','Selected uncomplicated cases may follow nonoperative pathways with shared decision-making.'],redFlags:['Peritonitis','Sepsis','Perforation','Abscess/mass'],takeaway:'Use selective imaging and early surgical input when appendicitis is likely.',guideline:'WSES Jerusalem Guidelines for acute appendicitis.'},
{id:36,department:'Surgery',title:'Small bowel obstruction',difficulty:'Advanced',vignette:'Wanita 58 tahun riwayat laparotomi mengalami nyeri kolik, muntah, distensi dan obstipasi.',vitals:'BP 108/68 · HR 116 · RR 24 · SpO₂ 97%',findings:['Prior abdominal surgery','Colicky pain','Vomiting/obstipation','Strangulation risk'],diagnosis:'Small bowel obstruction, likely adhesional.',differentials:['Ileus','Hernia obstruction','Colorectal obstruction','Mesenteric ischemia'],investigations:['CBC/electrolytes/lactate','CT abdomen with contrast when appropriate','Hernia examination'],reasoning:['Pertanyaan utama adalah apakah ada ischemia/strangulation.','Tachycardia, continuous pain, lactate elevation atau peritonitis meningkatkan urgensi surgery.'],management:['IV crystalloid and electrolyte correction.','NPO and NG decompression when indicated.','Early surgical review.','Urgent surgery for ischemia, strangulation, perforation or failed conservative management.'],redFlags:['Continuous severe pain','Peritonitis','Fever','Lactate elevation','Closed-loop obstruction'],takeaway:'Differentiate uncomplicated obstruction from strangulation requiring urgent surgery.',guideline:'WSES/Bologna guidelines for adhesive small bowel obstruction.'},
{id:37,department:'Surgery',title:'Acute calculous cholecystitis',difficulty:'Intermediate',vignette:'Wanita 45 tahun nyeri RUQ, demam dan Murphy sign positif.',vitals:'BP 126/78 · HR 108 · RR 20 · T 38.3°C',findings:['RUQ pain','Fever','Murphy sign','Assess CBD obstruction'],diagnosis:'Acute calculous cholecystitis.',differentials:['Biliary colic','Cholangitis','Hepatitis','Peptic ulcer disease'],investigations:['CBC/LFT/lipase','RUQ ultrasound','Further imaging if diagnosis uncertain or complications suspected'],reasoning:['Jaundice/cholestatic labs suggest CBD obstruction and may shift pathway to cholangitis/ERCP.'],management:['Analgesia and hydration.','Antibiotics when indicated.','Early laparoscopic cholecystectomy when suitable.','ERCP for appropriate CBD obstruction/cholangitis.'],redFlags:['Jaundice + fever','Shock','Peritonitis','Sepsis'],takeaway:'Always assess whether disease is isolated gallbladder inflammation or includes CBD obstruction.',guideline:'Tokyo Guidelines for acute cholecystitis/cholangitis.'},
{id:38,department:'Urology',title:'Infected obstructed urinary system',difficulty:'Advanced',vignette:'Pria 52 tahun nyeri pinggang, demam 39°C dan menggigil. CT menunjukkan batu ureter dengan hydronephrosis.',vitals:'BP 92/58 · HR 124 · RR 26 · T 39.0°C',findings:['Obstructing stone','Fever/sepsis','Hydronephrosis','Need urgent drainage'],diagnosis:'Obstructed infected urinary system / urosepsis.',differentials:['Pyelonephritis without obstruction','Renal infarction','AAA'],investigations:['Cultures','CBC/CMP/lactate','Imaging to define obstruction','Assess renal function'],reasoning:['Antibiotics alone tidak cukup karena infected obstruction membutuhkan source control.'],management:['IV antibiotics promptly.','Sepsis resuscitation.','Urgent decompression with ureteric stent or nephrostomy.','Definitive stone treatment after infection controlled.'],redFlags:['Shock','Anuria','AKI','Solitary kidney','Bilateral obstruction'],takeaway:'Drain the infected obstructed system urgently.',guideline:'EAU Urolithiasis and Urological Infection guidance.'},
{id:39,department:'Urology',title:'Acute urinary retention',difficulty:'Intermediate',vignette:'Pria 68 tahun LUTS mengalami nyeri suprapubik dan tidak dapat berkemih 12 jam.',vitals:'BP 148/84 · HR 96 · RR 18',findings:['Painful inability to void','Palpable bladder','BPH history','Assess cause'],diagnosis:'Acute urinary retention, likely bladder outlet obstruction from BPH.',differentials:['Urethral stricture','Neurogenic bladder','Medication-induced retention','Clot retention'],investigations:['Bladder scan when available','Urinalysis','Creatinine','Medication review'],reasoning:['Decompression adalah tindakan segera; selanjutnya cari precipitant dan rencanakan trial without catheter.'],management:['Prompt bladder decompression.','Alpha-blocker when appropriate.','Treat precipitating factor.','Trial without catheter after suitable interval.','Urology if catheterization difficult or complicated.'],redFlags:['Fever/sepsis','AKI','Hematuria/clot','Trauma','Failed catheterization'],takeaway:'Relieve obstruction first, then establish the cause and catheter plan.',guideline:'EAU Male LUTS/BPH guidance.'},
{id:40,department:'Dermatology',title:'Cellulitis dengan systemic features',difficulty:'Intermediate',vignette:'Wanita 50 tahun diabetes dengan tungkai merah, hangat, nyeri dan demam. Tidak ada crepitus.',vitals:'BP 110/70 · HR 112 · RR 22 · T 38.6°C',findings:['Diffuse erythema','Fever/tachycardia','Diabetes','Must exclude necrotizing infection'],diagnosis:'Nonpurulent cellulitis with systemic inflammatory response.',differentials:['DVT','Necrotizing fasciitis','Contact dermatitis','Gout'],investigations:['Clinical assessment','Ultrasound if abscess/DVT concern','Cultures in severe selected cases','Labs if systemic illness'],reasoning:['Pain out of proportion, bullae, rapid progression or shock should trigger necrotizing fasciitis pathway.'],management:['Appropriate anti-streptococcal/MSSA therapy per local guideline.','IV therapy if severe.','Drain abscess if present.','Treat portal of entry and glycemia.','Reassess response.'],redFlags:['Pain out of proportion','Bullae','Skin anesthesia','Crepitus','Rapid progression','Shock'],takeaway:'The dangerous alternative is necrotizing fasciitis—look for disproportionate pain and rapid progression.',guideline:'IDSA Skin and Soft Tissue Infection guideline; local antimicrobial guideline.'},
{id:41,department:'Dermatology',title:'SJS/TEN akibat obat',difficulty:'Advanced',vignette:'Pria 42 tahun 10 hari setelah obat baru mengalami demam, nyeri kulit, epidermal detachment dan erosi mukosa.',vitals:'BP 104/66 · HR 122 · RR 24 · T 39.2°C',findings:['Recent drug exposure','Mucosal involvement','Skin pain/detachment','Systemic toxicity'],diagnosis:'Suspected Stevens-Johnson syndrome/toxic epidermal necrolysis spectrum.',differentials:['DRESS','SSSS','Erythema multiforme','Pemphigus'],investigations:['Dermatology assessment and biopsy','BSA detachment estimation','CBC/CMP','Eye and mucosal assessment'],reasoning:['Drug withdrawal adalah intervensi pertama yang paling penting.','Ocular involvement dapat menyebabkan sequelae permanen.'],management:['Stop culprit/nonessential drugs immediately.','Burn/ICU/dermatology center supportive care.','Fluid/electrolyte management.','Pain and wound care.','Early ophthalmology assessment.'],redFlags:['Rapid progression','Large BSA','Ocular disease','Sepsis/shock','Airway involvement'],takeaway:'Withdraw the culprit drug immediately and transfer to appropriate expert care.',guideline:'International SJS/TEN management recommendations and burn/dermatology protocols.'},
{id:42,department:'Nephrology',title:'Acute kidney injury dengan oliguria',difficulty:'Advanced',vignette:'Pria 71 tahun setelah diare berat menjadi oliguria. Kreatinin naik dari 1.0 menjadi 3.0 mg/dL.',vitals:'BP 94/60 · HR 116 · RR 20',findings:['AKI','Oliguria','Possible hypovolemia','Need exclude obstruction/nephrotoxins'],diagnosis:'AKI, likely pre-renal/acute tubular injury spectrum.',differentials:['Obstruction','GN','AIN','Cardiorenal syndrome'],investigations:['Urinalysis/microscopy','Renal function/electrolytes','Medication review','Renal ultrasound if obstruction possible','Serial urine output'],reasoning:['AKI adalah sindrom; cari penyebab, koreksi perfusion dan monitor complications.','Creatinine alone should not dictate dialysis.'],management:['Restore perfusion if hypovolemic with careful reassessment.','Stop nephrotoxins and adjust doses.','Treat sepsis/underlying cause.','Avoid unnecessary nephrotoxic exposures.','Dialysis for standard urgent indications.'],redFlags:['Refractory hyperkalemia','Severe acidosis','Pulmonary edema','Uremic complications','Anuria'],takeaway:'Treat the cause and complications, not the creatinine number alone.',guideline:'KDIGO Acute Kidney Injury guidance.'},
{id:43,department:'Nephrology',title:'Nephrotic syndrome',difficulty:'Intermediate',vignette:'Wanita 35 tahun edema generalisata, proteinuria 4+, albumin 2.1 g/dL, creatinine normal.',vitals:'BP 148/92 · HR 86 · SpO₂ 97%',findings:['Heavy proteinuria','Hypoalbuminemia','Edema','Thrombosis/infection risk'],diagnosis:'Nephrotic syndrome.',differentials:['Heart failure','Cirrhosis','Protein-losing enteropathy','Advanced CKD'],investigations:['Quantify proteinuria','Urinalysis','Renal function','Secondary-cause workup','Nephrology evaluation/biopsy when indicated'],reasoning:['Nephrotic syndrome adalah syndrome, bukan etiologic diagnosis.','Immunosuppression tidak boleh diberikan otomatis tanpa diagnosis yang tepat.'],management:['Salt restriction and edema control.','ACEi/ARB for proteinuria when appropriate.','Diuretics titrated to edema.','Vaccination/infection prevention.','Etiology-specific therapy after diagnosis.'],redFlags:['Thrombosis','Infection','AKI','Respiratory compromise from edema'],takeaway:'Find the cause before committing to disease-specific immunosuppression.',guideline:'KDIGO Glomerular Diseases guidance.'},
{id:44,department:'Gastroenterology',title:'Acute pancreatitis',difficulty:'Intermediate',vignette:'Pria 48 tahun nyeri epigastrium hebat menjalar ke punggung, muntah dan lipase >3× normal.',vitals:'BP 108/70 · HR 112 · RR 24 · T 38.1°C',findings:['Typical pain','Lipase >3× ULN','Assess organ failure','Gallstones/alcohol possible'],diagnosis:'Acute pancreatitis.',differentials:['Perforated ulcer','ACS','Mesenteric ischemia','Biliary colic'],investigations:['Diagnosis by 2 of 3 criteria','Ultrasound for gallstones','Labs for severity/etiology','Imaging if diagnosis uncertain or complications suspected'],reasoning:['Early care focuses on appropriate fluid, analgesia and enteral nutrition.','Routine prophylactic antibiotics are not indicated in sterile pancreatitis.'],management:['Goal-directed isotonic/balanced crystalloid.','Analgesia/antiemetics.','Early oral/enteral feeding as tolerated.','Treat biliary obstruction/cholangitis urgently.','ICU if persistent organ failure.'],redFlags:['Shock','Hypoxemia','AKI','Persistent organ failure','Necrosis/infection'],takeaway:'Modern pancreatitis care is active supportive care—not prolonged NPO by default.',guideline:'ACG Acute Pancreatitis Guideline.'},
{id:45,department:'Infectious Disease',title:'Acute bacterial meningitis',difficulty:'Advanced',vignette:'Pria 19 tahun demam tinggi, sakit kepala, muntah, kaku kuduk dan penurunan kesadaran.',vitals:'BP 106/64 · HR 118 · RR 26 · T 39.5°C · GCS 13',findings:['Fever + meningism','Altered consciousness','Sepsis risk','Antibiotic time-critical'],diagnosis:'Suspected acute bacterial meningitis.',differentials:['Encephalitis','SAH','Brain abscess','Sepsis-associated encephalopathy'],investigations:['Blood cultures','Glucose','CBC/CMP','LP when safe','CT before LP only when guideline indications present'],reasoning:['Antibiotik tidak boleh tertunda oleh imaging yang tidak diperlukan.','LP dilakukan bila aman dan tidak menyebabkan keterlambatan terapi.'],management:['Prompt empiric IV antibiotics based on age/risk/local resistance.','Dexamethasone when indicated.','Airway/ICP/seizure management.','Droplet precautions if meningococcal disease suspected.'],redFlags:['GCS decline','Focal deficit','Papilledema','Shock','Seizures'],takeaway:'Treat suspected bacterial meningitis immediately; diagnostics must fit around antimicrobial urgency.',guideline:'WHO meningitis guidance and IDSA/local protocols.'},
{id:46,department:'Infectious Disease',title:'Dengue dengan warning signs',difficulty:'Advanced',vignette:'Remaja 16 tahun hari ke-4 demam mengalami nyeri abdomen, muntah persisten, hematokrit meningkat dan trombosit menurun.',vitals:'BP 104/72 · HR 112 · RR 22 · T 37.2°C',findings:['Critical phase day 3–7','Abdominal pain','Persistent vomiting','Hemoconcentration'],diagnosis:'Dengue with warning signs.',differentials:['Sepsis','Malaria','Acute hepatitis','Appendicitis'],investigations:['Serial hematocrit','Platelets','Liver/renal function','Perfusion and urine output'],reasoning:['Plasma leakage dapat berkembang cepat saat fase kritis.','Fluid harus dititrasi dengan serial perfusion/hematocrit untuk mencegah overload saat reabsorption.'],management:['Careful isotonic crystalloid according to hemodynamic status.','Paracetamol for fever/pain.','Avoid NSAIDs/aspirin.','Blood products for significant bleeding indications.','Escalate if shock/organ dysfunction.'],redFlags:['Shock','Respiratory distress from fluid overload/leakage','Severe bleeding','Organ impairment'],takeaway:'Dengue fluid therapy requires frequent reassessment and avoidance of indiscriminate boluses.',guideline:'WHO Dengue clinical management guidance.'},
{id:47,department:'Infectious Disease',title:'Severe falciparum malaria',difficulty:'Advanced',vignette:'Pria 30 tahun pulang dari daerah endemis, demam, penurunan kesadaran, ikterus dan parasitemia tinggi.',vitals:'BP 92/56 · HR 124 · RR 28 · T 39.6°C · GCS 11',findings:['Exposure/travel risk','Altered consciousness','High parasitemia','Multiorgan involvement'],diagnosis:'Severe falciparum malaria.',differentials:['Sepsis','Meningitis','Dengue','Viral encephalitis'],investigations:['Blood film/RDT','Parasitemia quantification','Glucose','CBC/CMP','Renal/liver function'],reasoning:['Severe malaria is a medical emergency.','Hypoglycemia, cerebral malaria, severe anemia, AKI and acidosis must be actively screened.'],management:['IV artesunate according to weight-based protocol.','Transition to complete oral ACT when able.','Treat hypoglycemia and organ complications.','Repeat parasitemia according to protocol.','Monitor delayed hemolysis after artesunate.'],redFlags:['Cerebral malaria','Hypoglycemia','Severe anemia','AKI','Acidosis','Shock'],takeaway:'Start parenteral antimalarial therapy promptly when severe malaria is strongly suspected.',guideline:'WHO Guidelines for Malaria.'},
{id:48,department:'Psychiatry',title:'Acute agitation dengan suicide risk',difficulty:'Advanced',vignette:'Pria 28 tahun mengatakan ingin mati, sangat gelisah dan membawa benda tajam. Sulit diajak bicara.',vitals:'BP 136/84 · HR 112 · RR 22 · SpO₂ 98%',findings:['Immediate self-harm risk','Access to lethal means','Agitation','Possible medical/toxic cause'],diagnosis:'Acute agitation with high suicide/self-harm risk.',differentials:['Intoxication/withdrawal','Delirium','Psychosis','Mania','CNS pathology'],investigations:['Rapid medical assessment','Glucose','Vitals','Toxicologic assessment when indicated','Suicide risk assessment when safely feasible'],reasoning:['Safety comes first.','Agitation can be medical, toxicologic or psychiatric and should not automatically be labeled psychiatric.'],management:['Remove lethal means and ensure staff safety.','Low-stimulation environment and verbal de-escalation.','Medication for severe agitation according to local emergency protocol.','Treat underlying medical/toxic cause.','Constant observation and psychiatric assessment when risk persists.'],redFlags:['Specific suicide plan','Command hallucinations','Delirium','Severe intoxication','Access to lethal means'],takeaway:'Secure the environment before attempting a detailed psychiatric interview.',guideline:'WHO mhGAP and local emergency psychiatry/suicide prevention protocols.'},
{id:49,department:'Endocrinology',title:'Thyroid storm',difficulty:'Advanced',vignette:'Wanita 35 tahun Graves disease tidak minum obat. Demam tinggi, agitasi, diare dan palpitasi.',vitals:'BP 146/82 · HR 156 irregular · RR 30 · T 40.1°C',findings:['High fever','Marked tachycardia/AF','CNS disturbance','GI symptoms','Known Graves'],diagnosis:'Thyroid storm.',differentials:['Sepsis','Serotonin syndrome','NMS','Malignant hyperthermia'],investigations:['TSH/free T4/T3','CBC/CMP','ECG','Identify precipitant','Liver function'],reasoning:['Diagnosis is clinical; do not wait for thyroid tests before treating a critically ill compatible patient.','Therapy blocks hormone synthesis and release while treating systemic complications.'],management:['ICU-level monitoring.','Beta-blocker carefully when hemodynamically appropriate.','Thionamide.','Iodine after thionamide.','Hydrocortisone and supportive cooling.','Treat precipitant.'],redFlags:['Heart failure','Shock','Severe arrhythmia','Altered consciousness','Hepatic dysfunction'],takeaway:'Treat the syndrome and precipitant simultaneously.',guideline:'American Thyroid Association hyperthyroidism/thyroid storm guidance.'},
{id:50,department:'Hematology',title:'Sickle-cell vaso-occlusive crisis',difficulty:'Intermediate',vignette:'Pria 24 tahun sickle-cell disease mengalami nyeri hebat punggung dan tungkai setelah dehidrasi.',vitals:'BP 118/72 · HR 108 · RR 20 · SpO₂ 97%',findings:['Known SCD','Severe pain','Possible dehydration trigger','Screen for acute chest syndrome'],diagnosis:'Vaso-occlusive pain crisis.',differentials:['Osteomyelitis','Septic arthritis','Acute chest syndrome','PE'],investigations:['Pain assessment','CBC/reticulocytes','Chest evaluation if symptoms','Infection workup when indicated'],reasoning:['Pain harus ditangani segera.','Pada saat yang sama, screen acute chest syndrome, infection dan anemia.'],management:['Prompt analgesia according to severity/protocol.','Hydration guided by clinical status; avoid overload.','Oxygen only if hypoxemic.','Treat infection when suspected.','Transfusion only for selected complications.'],redFlags:['Fever','Chest pain/cough/hypoxemia','Neurologic deficit','Rapid Hb drop','Priapism'],takeaway:'Treat pain promptly while actively looking for life-threatening complications.',guideline:'ASH sickle-cell disease guidelines and local hematology protocol.'}
];
export default cases;
